// CreatorDB niche name → ID resolver. Loads static mapping files generated by
// scripts/fetch-creatordb-niches.ts and resolves user-typed niche names to
// CreatorDB taxonomy IDs for use in search filters.

import { distance } from 'fastest-levenshtein'

interface NicheEntry {
  id: string
  name: string
  category: string
  channelCount: number
}

type NicheMap = Record<string, NicheEntry[]>

export interface NicheMatchExact {
  term: string
  translatedFrom?: string // original non-English term if translated
  ids: string[]
}

export interface NicheMatchFuzzy {
  term: string
  translatedFrom?: string // original non-English term if translated
  matchedName: string
  score: number
  ids: string[]
}

export interface NicheUnmatched {
  term: string
  suggestions: string[]
}

export interface NicheResolveResult {
  matched: NicheMatchExact[]
  fuzzyMatched: NicheMatchFuzzy[]
  unmatched: NicheUnmatched[]
  ids: string[]
}

// ── Mapping cache ──────────────────────────────────────────────────────────────

const mapCache: Record<string, NicheMap> = {}

function loadMap(platform: string): NicheMap {
  if (mapCache[platform]) return mapCache[platform]
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const data = require(`../data/creatordb-niches/${platform}.json`)
    mapCache[platform] = data
    return data
  } catch {
    console.warn(`[creatordb-niches] No mapping file for ${platform}`)
    mapCache[platform] = {}
    return {}
  }
}

// Exposed for tests
export function _loadMap(platform: string): NicheMap {
  return loadMap(platform)
}

// ── Normalization ──────────────────────────────────────────────────────────────

function normalizeKey(name: string): string {
  return name
    .toLowerCase()
    .trim()
    // Strip ASCII punctuation but keep letters, digits, spaces, and non-Latin scripts
    .replace(/[\u0021-\u002F\u003A-\u0040\u005B-\u0060\u007B-\u007E]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
}

// ── Similarity (Levenshtein-based, scaled 0–100) ─────────────────────────────

function similarity(a: string, b: string): number {
  const maxLen = Math.max(a.length, b.length)
  if (maxLen === 0) return 100
  return Math.round((1 - distance(a, b) / maxLen) * 100)
}

