function hasNonLatinChars(text: string): boolean {
  return /[^\u0000-\u024F\s]/.test(text)
}

export function translateTerm(term: string): string | null {
  const trimmed = term.trim()
  // Direct lookup
  if (NICHE_TRANSLATIONS.has(trimmed)) return NICHE_TRANSLATIONS.get(trimmed)!
  // Lowercase lookup (for Latin-script translations like Spanish/French)
  const lower = trimmed.toLowerCase()
  if (NICHE_TRANSLATIONS.has(lower)) return NICHE_TRANSLATIONS.get(lower)!
  return null
}

// ── Resolver ───────────────────────────────────────────────────────────────────

const FUZZY_THRESHOLD = 80
const MAX_SUGGESTIONS = 3
const MAX_IDS = 100

export function resolveNiches(
  platform: string,
  userInput: string,
): NicheResolveResult {
  const map = loadMap(platform)
  const allNames = Object.keys(map)

  // Split on commas, semicolons, " and ", Chinese comma/pause mark
  const terms = userInput
    .split(/[,;，、]|\band\b/i)
    .map((t) => t.trim())
    .filter(Boolean)

  const matched: NicheMatchExact[] = []
  const fuzzyMatched: NicheMatchFuzzy[] = []
  const unmatched: NicheUnmatched[] = []
  const allIds = new Set<string>()

  for (const rawTerm of terms) {
    // Translate non-English terms before matching
    const translated = translateTerm(rawTerm)
    const effectiveTerm = translated ?? rawTerm
    const key = normalizeKey(effectiveTerm)
    if (!key) continue

    // Exact match
    if (map[key]) {
      const ids = map[key].map((e) => e.id)
      matched.push({
        term: effectiveTerm,
        ...(translated ? { translatedFrom: rawTerm } : {}),
        ids,
      })
      for (const id of ids) allIds.add(id)
      continue
    }

    // Fuzzy match — compare against all names
    let bestName: string | null = null
    let bestScore = 0
    let bestChannelCount = 0

    for (const candidate of allNames) {
      const score = similarity(key, candidate)
      if (score >= FUZZY_THRESHOLD) {
        const topCount = map[candidate][0]?.channelCount ?? 0
        if (
          score > bestScore ||
          (score === bestScore && topCount > bestChannelCount)
        ) {
          bestScore = score
          bestName = candidate
          bestChannelCount = topCount
        }
      }
    }

    if (bestName) {
      const ids = map[bestName].map((e) => e.id)
      fuzzyMatched.push({
        term: effectiveTerm,
        ...(translated ? { translatedFrom: rawTerm } : {}),
        matchedName: map[bestName][0].name, // original casing
        score: bestScore,
        ids,
      })
      for (const id of ids) allIds.add(id)
      continue
    }

    // Unmatched — find top 3 closest as suggestions
    const scored = allNames
      .map((name) => ({ name: map[name][0].name, score: similarity(key, name) }))
      .sort((a, b) => b.score - a.score)
      .slice(0, MAX_SUGGESTIONS)
    unmatched.push({
      term: rawTerm,
      suggestions: scored.map((s) => s.name),
    })
  }

  // Deduplicate and cap at 100 IDs
  let ids = [...allIds]
  if (ids.length > MAX_IDS) {
    // Keep top 100 by channelCount — need to look up counts
    const entries = new Map<string, number>()
    for (const name of allNames) {
      for (const entry of map[name]) {
        entries.set(entry.id, entry.channelCount)
      }
    }
    ids = ids
      .sort((a, b) => (entries.get(b) ?? 0) - (entries.get(a) ?? 0))
      .slice(0, MAX_IDS)
    console.warn(
      `[creatordb-niches] ${allIds.size} niche IDs exceed the 100 cap; keeping top ${MAX_IDS} by channelCount`,
    )
  }

  return { matched, fuzzyMatched, unmatched, ids }
}
